/* eslint-disable no-console */
import React, { useState, useEffect } from "react";

/**
 * SafetyCheck.jsx
 * Solid tourism UI with reliable background (gradient + image fallback).
 * If the remote image fails to load, the gradient will still show.
 *
 * If you want the BEST reliability, follow the "Local image" instructions below
 * after this code block.
 */

export default function SafetyCheck() {
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [result, setResult] = useState("");
  const [loading, setLoading] = useState(false);
  const [autoFetched, setAutoFetched] = useState(false);

  useEffect(() => {
    // try auto-fetching once on load (optional)
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setLatitude(position.coords.latitude.toFixed(4));
          setLongitude(position.coords.longitude.toFixed(4));
          setAutoFetched(true);
        },
        () => {
          // ignore silently
        }
      );
    }
  }, []);

  const handleCheckSafety = async () => {
    if (!latitude || !longitude) {
      alert("Please allow location access or enter lat/lng first.");
      return;
    }
    try {
      setLoading(true);
      const response = await fetch("http://localhost:5000/api/safety/check", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          latitude: parseFloat(latitude),
          longitude: parseFloat(longitude),
        }),
      });
      const data = await response.json();
      setResult(data.message);
    } catch (err) {
      console.error(err);
      setResult("⚠️ Error checking safety");
    } finally {
      setLoading(false);
    }
  };

  const handleFetchLocation = () => {
    if (!navigator.geolocation) {
      alert("Geolocation not supported");
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setLatitude(pos.coords.latitude.toFixed(4));
        setLongitude(pos.coords.longitude.toFixed(4));
        setAutoFetched(true);
      },
      (err) => {
        console.error("Location error:", err);
        alert("Allow location access in the browser.");
      }
    );
  };

  return (
    <div style={rootStyle}>
      <style>{`
        @keyframes floatUp {
          from { transform: translateY(20px); opacity: 0; }
          to   { transform: translateY(0); opacity: 1; }
        }
      `}</style>

      <div style={cardStyle}>
        <h1 style={{ margin: 0, color: "#3b1f04" }}>🧭 Kashi Rath — Tourist Safety</h1>
        <p style={{ marginTop: 6, color: "#5b3a1a" }}>
          Auto-detect your location and check safety for the area.
        </p>

        <div style={{ marginTop: 18 }}>
          <div style={{ display: "flex", gap: 8, justifyContent: "center", marginBottom: 12 }}>
            <button onClick={handleFetchLocation} style={primaryBtn}>
              📍 Fetch My Location
            </button>
            <button onClick={handleCheckSafety} style={secondaryBtn} disabled={loading}>
              {loading ? "Checking..." : "🔒 Check Safety"}
            </button>
          </div>

          <div style={{ display: "flex", gap: 8, justifyContent: "center", marginBottom: 12 }}>
            <input
              value={latitude}
              onChange={(e) => setLatitude(e.target.value)}
              placeholder="Latitude"
              style={inputSmall}
            />
            <input
              value={longitude}
              onChange={(e) => setLongitude(e.target.value)}
              placeholder="Longitude"
              style={inputSmall}
            />
          </div>

          {result && (
            <div
              style={{
                marginTop: 12,
                padding: "10px 14px",
                borderRadius: 10,
                backgroundColor: result.toLowerCase().includes("safe") ? "#e6ffed" : "#ffe6e6",
                color: result.toLowerCase().includes("safe") ? "#08603a" : "#8a1b1b",
                fontWeight: 600,
              }}
            >
              {result}
            </div>
          )}

          {!autoFetched && (
            <div style={{ marginTop: 10, color: "#6b4d2b", fontSize: 13 }}>
              Allow browser location for automatic detection.
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ---------- styles ---------- */

// rootStyle uses a layered background: gradient on top of image. If image fails, the gradient is visible.
const rootStyle = {
  minHeight: "100vh",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  fontFamily: "'Poppins', sans-serif",
  // Layered background: gradient first, image second. If image fails, gradient still visible.
  backgroundImage:
    `linear-gradient(135deg, rgba(255,156,66,0.9), rgba(255,111,0,0.85)), 
     url('https://images.unsplash.com/photo-1603262110263-fb7b3c88792a?auto=format&fit=crop&w=1500&q=80')`,
  backgroundSize: "cover",
  backgroundPosition: "center",
  backgroundRepeat: "no-repeat",
  padding: 20,
};

// floating glass card
const cardStyle = {
  width: 420,
  maxWidth: "92%",
  background: "rgba(255,255,255,0.92)",
  borderRadius: 18,
  padding: 26,
  boxShadow: "0 12px 40px rgba(0,0,0,0.25)",
  animation: "floatUp 450ms ease both",
  textAlign: "center",
};

const primaryBtn = {
  background: "#ff6f00",
  color: "white",
  border: "none",
  padding: "10px 14px",
  borderRadius: 10,
  cursor: "pointer",
  fontWeight: 600,
};

const secondaryBtn = {
  background: "#085078",
  color: "white",
  border: "none",
  padding: "10px 14px",
  borderRadius: 10,
  cursor: "pointer",
  fontWeight: 600,
};

const inputSmall = {
  padding: "8px 10px",
  borderRadius: 8,
  border: "1px solid #ddd",
  width: 160,
  textAlign: "center",
};
